// [A2] paso 2: leer cursor de static data + fetch ERP pending-vtiger-sync
const staticData = $getWorkflowStaticData('global');
const cursor = staticData.lastAuditLogId || 0;

const erpUrl = $env.ERP_INTERNAL_URL || 'https://erp.livskin.site';
const token = $env.AUDIT_INTERNAL_TOKEN;
if (!token) throw new Error('AUDIT_INTERNAL_TOKEN no configurado en n8n env');

const url = `${erpUrl}/api/internal/leads/pending-vtiger-sync?since=${cursor}&limit=50`;
const resp = await this.helpers.httpRequest({
  method: 'GET',
  url,
  headers: { 'X-Internal-Token': token },
  json: true,
  timeout: 15000,
});

if (!resp || typeof resp.count !== 'number') {
  throw new Error('ERP response invalida: ' + JSON.stringify(resp).slice(0, 200));
}

return [{
  json: {
    _cursor_in: cursor,
    _count: resp.count,
    _next_cursor: resp.next_cursor,
    _has_more: resp.has_more,
    items: resp.items || [],
  }
}];

// [A2] paso 4: per-item Vtiger auth + update leadstatus + emit audit
// Procesa TODOS los items del batch in-loop. Errores per-item NO bloquean otros items.

const crypto = require('crypto');
const input = $input.first().json;
const items = input.items || [];

const vtigerUrl = $env.VTIGER_URL;
const vtigerUser = $env.VTIGER_API_USER;
const vtigerKey = $env.VTIGER_API_ACCESSKEY;
const erpUrl = $env.ERP_INTERNAL_URL || 'https://erp.livskin.site';
const auditToken = $env.AUDIT_INTERNAL_TOKEN;

// Vtiger auth: getchallenge → md5(token + accesskey) → login → sessionName
async function vtigerLogin() {
  const challengeResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${vtigerUrl}/webservice.php`,
    qs: { operation: 'getchallenge', username: vtigerUser },
    json: true,
    timeout: 10000,
  });
  if (!challengeResp.success) throw new Error('getchallenge failed: ' + JSON.stringify(challengeResp));
  const accessHash = crypto.createHash('md5').update(challengeResp.result.token + vtigerKey).digest('hex');
  const loginResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${vtigerUrl}/webservice.php`,
    body: { operation: 'login', username: vtigerUser, accessKey: accessHash },
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    json: true,
    timeout: 10000,
  });
  if (!loginResp.success) throw new Error('login failed: ' + JSON.stringify(loginResp));
  return loginResp.result.sessionName;
}

async function vtigerUpdate(sessionName, vtigerId, newLeadstatus) {
  // Vtiger update requiere el element JSON con TODOS los fields no null O usar 'revise' (partial update)
  const reviseResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${vtigerUrl}/webservice.php`,
    body: {
      operation: 'revise',
      sessionName,
      element: JSON.stringify({ id: vtigerId, leadstatus: newLeadstatus }),
    },
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    json: true,
    timeout: 15000,
  });
  return reviseResp;
}

async function emitAuditEvent(action, after_state, sourceAuditLogId) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${erpUrl}/api/internal/audit-event`,
    headers: { 'X-Internal-Token': auditToken, 'Content-Type': 'application/json' },
    body: {
      action,
      category: 'tracking',
      entity_type: 'lead',
      entity_id: after_state.cod_lead || null,
      after_state,
      result: action.endsWith('failed') ? 'error' : 'success',
      audit_metadata: { source_audit_log_id: sourceAuditLogId, workflow: 'A2' },
    },
    json: true,
    timeout: 10000,
  });
}

const results = [];
let sessionName = null;

try {
  sessionName = await vtigerLogin.call(this);
} catch (err) {
  // Si falla auth Vtiger, NO avanzar cursor — proximo cron retoma desde mismo punto
  return [{ json: { _error: 'vtiger_auth_failed', _message: err.message, _items_processed: 0, _max_id_processed: input._cursor_in } }];
}

let maxIdSuccess = input._cursor_in;

for (const item of items) {
  try {
    const updateResp = await vtigerUpdate.call(this, sessionName, item.vtiger_id, item.target_vtiger_leadstatus);
    if (updateResp && updateResp.success) {
      await emitAuditEvent.call(this, 'tracking.vtiger_leadstatus_synced', {
        cod_lead: item.cod_lead,
        vtiger_id: item.vtiger_id,
        old_leadstatus: item.current_erp_estado_lead,
        new_leadstatus: item.target_vtiger_leadstatus,
        source_audit_log_id: item.audit_log_id,
      }, item.audit_log_id);
      results.push({ status: 'synced', audit_log_id: item.audit_log_id, vtiger_id: item.vtiger_id });
      if (item.audit_log_id > maxIdSuccess) maxIdSuccess = item.audit_log_id;
    } else {
      throw new Error('Vtiger revise failed: ' + JSON.stringify(updateResp).slice(0, 200));
    }
  } catch (err) {
    await emitAuditEvent.call(this, 'tracking.vtiger_leadstatus_sync_failed', {
      cod_lead: item.cod_lead,
      vtiger_id: item.vtiger_id,
      attempted_leadstatus: item.target_vtiger_leadstatus,
      error_message: String(err.message || err).slice(0, 500),
      source_audit_log_id: item.audit_log_id,
    }, item.audit_log_id);
    results.push({ status: 'failed', audit_log_id: item.audit_log_id, vtiger_id: item.vtiger_id, error: String(err.message || err).slice(0, 200) });
  }
}

return [{ json: { _items_processed: results.length, _max_id_processed: maxIdSuccess, _results: results } }];

// [A2] paso 5: persistir cursor avanzado en static data
// Solo avanza cursor a max audit_log_id de items SUCCESSFULLY synced.
// Items failed quedan en queue para retry en proximos crons.
const result = $input.first().json;
const staticData = $getWorkflowStaticData('global');
staticData.lastAuditLogId = result._max_id_processed;
staticData.lastRunAt = new Date().toISOString();
staticData.lastBatchSize = result._items_processed;
return [{ json: { _cursor_after: result._max_id_processed, _persisted: true, _summary: result } }];
